<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { cambiarEstadoTipoRelacion, guardarTipoRelacion, listarTiposRelacion, operacionLabels, operaciones } from '../services/tiposRelacion'
import type { TipoOperacion, TipoRelacion, TipoRelacionPayload } from '../interfaces/tiposRelacion.interface'
type EstadoFiltro='todos'|'activo'|'inactivo';const rows=ref<TipoRelacion[]>([]),criterio=ref(''),operacionFiltro=ref<TipoOperacion|'todos'>('todos'),estadoFiltro=ref<EstadoFiltro>('todos'),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null);const defaults:TipoRelacionPayload={codigo:'',descripcion:'',tipo_operacion:'SUMA',requiere_factor:false,requiere_limite:false,requiere_condicion:false};const form=reactive<TipoRelacionPayload>({...defaults});const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
const filtered=computed(()=>{const q=criterio.value.trim().toLocaleLowerCase();return rows.value.filter(x=>(!q||`${x.codigo} ${x.descripcion}`.toLocaleLowerCase().includes(q))&&(operacionFiltro.value==='todos'||x.tipo_operacion===operacionFiltro.value)&&(estadoFiltro.value==='todos'||x.estado===(estadoFiltro.value==='activo')))})
const requirements=computed(()=>[form.requiere_factor?'Factor':'',form.requiere_limite?'Límite':'',form.requiere_condicion?'Condición':''].filter(Boolean))
async function load(){loading.value=true;error.value='';try{rows.value=await listarTiposRelacion()}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(x?:TipoRelacion){editing.value=x?.id??null;Object.assign(form,x?{codigo:x.codigo,descripcion:x.descripcion,tipo_operacion:x.tipo_operacion,requiere_factor:x.requiere_factor,requiere_limite:x.requiere_limite,requiere_condicion:x.requiere_condicion}:{...defaults});error.value='';modal.value=true}
function validate(){if(!form.codigo.trim())return 'El código es obligatorio.';if(form.codigo.trim().length>30)return 'El código admite como máximo 30 caracteres.';if(!form.descripcion.trim())return 'La descripción es obligatoria.';if(form.descripcion.trim().length>150)return 'La descripción admite como máximo 150 caracteres.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarTipoRelacion(editing.value,{...form,codigo:form.codigo.trim().toUpperCase(),descripcion:form.descripcion.trim()});modal.value=false;success.value=`Tipo de relación ${editing.value?'actualizado':'registrado'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(x:TipoRelacion){const action=x.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} el tipo de relación ${x.descripcion}?`))return;try{const r=await cambiarEstadoTipoRelacion(x.id);x.estado=r.estado;success.value=r.message??`Tipo de relación ${x.estado?'activado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}
function clear(){criterio.value='';operacionFiltro.value='todos';estadoFiltro.value='todos'};onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Tipos de relación</nav><header class="hero"><div class="mark">TR</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Tipos de relación</h1><p>Operaciones y requerimientos aplicables entre conceptos de planilla.</p></div><strong>{{filtered.length}} de {{rows.length}}</strong><button @click="open()">+ Nuevo tipo</button></header><aside class="help"><b>Operaciones disponibles</b><span>Suma y resta combinan valores; multiplica y divide usan factores; límite restringe resultados y condicional evalúa reglas lógicas.</span></aside><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="criterio" placeholder="Código o descripción"></label><label>Operación<select v-model="operacionFiltro"><option value="todos">Todas</option><option v-for="x in operaciones" :key="x" :value="x">{{operacionLabels[x]}}</option></select></label><label>Estado<select v-model="estadoFiltro"><option value="todos">Todos</option><option value="activo">Activos</option><option value="inactivo">Inactivos</option></select></label><button class="soft" @click="clear">Limpiar</button></section><section class="table-card"><header><small>REGLAS DE CÁLCULO</small><h2>Tipos registrados</h2></header><div v-if="loading" class="empty">Consultando tipos de relación…</div><div v-else-if="!filtered.length" class="empty">No se encontraron tipos de relación.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Código</th><th>Descripción</th><th>Operación</th><th>Factor</th><th>Límite</th><th>Condición</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td>{{x.id}}</td><td><b>{{x.codigo}}</b></td><td>{{x.descripcion}}</td><td><span class="operation" :data-operation="x.tipo_operacion">{{operacionLabels[x.tipo_operacion]}}</span></td><td><span :class="x.requiere_factor?'yes':'no'">{{x.requiere_factor?'Sí':'No'}}</span></td><td><span :class="x.requiere_limite?'yes':'no'">{{x.requiere_limite?'Sí':'No'}}</span></td><td><span :class="x.requiere_condicion?'yes':'no'">{{x.requiere_condicion?'Sí':'No'}}</span></td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">TR</div><div><small>REGLAS DE CÁLCULO</small><h2>{{editing?'Editar':'Registrar'}} tipo de relación</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="30" placeholder="Ej. SUM01" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Tipo de operación *<select v-model="form.tipo_operacion"><option v-for="x in operaciones" :key="x" :value="x">{{operacionLabels[x]}}</option></select></label><label class="full">Descripción *<input v-model="form.descripcion" maxlength="150"></label><h3>Requerimientos</h3><div class="checks"><label><input v-model="form.requiere_factor" type="checkbox"><b>Requiere factor</b><small>Valor numérico multiplicador o divisor.</small></label><label><input v-model="form.requiere_limite" type="checkbox"><b>Requiere límite</b><small>Valor máximo o mínimo aplicable.</small></label><label><input v-model="form.requiere_condicion" type="checkbox"><b>Requiere condición</b><small>Expresión lógica para ejecutar la relación.</small></label></div></div><aside v-if="form.codigo&&form.descripcion" class="preview"><small>VISTA PREVIA</small><p><b>{{form.codigo}}</b> — {{form.descripcion}}</p><span>Operación: {{operacionLabels[form.tipo_operacion]}} · Requiere: {{requirements.length?requirements.join(', '):'ningún parámetro adicional'}}</span></aside><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
