t-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive,.operation,.yes,.no{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active,.yes,.operation[data-operation=SUMA]{color:#287154;background:#e6f7ee}.inactive,.operation[data-operation=RESTA]{color:#9d4046;background:#fdebed}.no{color:#667078;background:#edf1f3}.operation{color:#315d92;background:#eaf3fb}.operation[data-operation=LIMITE]{color:#89600d;background:#fff1d0}.operation[data-operation=CONDICIONAL]{color:#655075;background:#f3ecf8}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(780px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.full,.grid h3,.checks{grid-column:1/-1}.grid h3{margin:12px 0 0;padding-bottom:5px;border-bottom:1px solid #e8ecee;font-size:.58rem}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.checks label{padding:10px;border-radius:7px;background:#f7f8f9;grid-template-columns:auto 1fr;gap:4px}.checks input{grid-row:span 2;width:auto;margin:2px}.checks small{color:#7e8a90}.preview{margin-top:14px;padding:12px;border-radius:7px;background:#f2f6fa}.preview p,.preview span{display:block;margin:6px 0 0;font-size:.52rem}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:800px){.hero,.filters,.help{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%;min-width:0}.grid,.checks{grid-template-columns:1fr}.full,.grid h3,.checks{grid-column:auto}.actions{min-width:140px}}
